-- MD2-7 phone alerts (Oct 14 2026), applied via Supabase MCP as migration md2_push_alerts,
-- plus the follow-up grant and cron job below. Edge function source: supabase/functions/myday-push/index.ts
-- (deployed with verify_jwt=false; POST is guarded by app_secrets.push_cron_secret, GET ?op=key only
-- returns the VAPID public key). VAPID keys are generated by the function itself on first run and
-- stored in app_secrets; no key value was ever handled by hand or by a session.
create extension if not exists pg_net;
create table if not exists public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  endpoint text not null unique, p256dh text not null, auth text not null,
  user_agent text, created_at timestamptz not null default now(), last_ok_at timestamptz
);
alter table public.push_subscriptions enable row level security;
create policy authenticated_all on public.push_subscriptions for all to authenticated using (true) with check (true);
create table if not exists public.push_log (
  kind text not null, day date not null, sent integer, note text, created_at timestamptz not null default now(),
  primary key (kind, day)
);
alter table public.push_log enable row level security;
create policy authenticated_all on public.push_log for all to authenticated using (true) with check (true);
create table if not exists public.app_secrets (name text primary key, value text not null, created_at timestamptz not null default now());
alter table public.app_secrets enable row level security;  -- no policies: service role only
insert into public.app_secrets (name, value) values ('push_cron_secret', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
on conflict (name) do nothing;
-- push_digest(p_now): returns {kind,title,body,url} or null. 08:00 London = morning (shift, chores due,
-- people to catch up with); Sunday 18:00 London = weekly review (if not written). Claims push_log so each
-- kind goes once a day. Full body: see the applied migration (pg_get_functiondef('public.push_digest')).
revoke all on function public.push_digest(timestamptz) from public, anon, authenticated;
grant execute on function public.push_digest(timestamptz) to service_role;
select cron.schedule('myday-push', '2 * * * *', $c$select net.http_post(url := 'https://gripopghczmrbrhqtqbm.supabase.co/functions/v1/myday-push', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select value from public.app_secrets where name = 'push_cron_secret')), body := '{}'::jsonb)$c$);
-- Verified: push_digest in a rolled-back tx (08:30 -> morning, same hour again -> null, Sun 18:10 -> review,
-- midday -> null); key generated on first GET; a send to a throwaway endpoint returned sent:1; a wrong
-- secret returned 403; a 410 endpoint was removed by the function itself (gone:1).
